/**
 * Card secondary layouts vs the server's own functions
 * (card_breakdown.compute_breakdown / card_metrics.numeric_layout_payload),
 * over the engine fixture, unmasked and under the `in_str` mask. Generated by
 * scripts/generate_fixture.py (`card_layouts`). Floats to 1e-9 relative.
 */
import { describe, expect, it } from 'vitest';

import { computeBreakdown, numericLayoutPayload, type ColumnGetter } from '../../src/cardLayouts';
import { expected, fixtureRef, openFixture } from './helpers';

type Case = { card: Record<string, unknown>; layout: string; payload: unknown };
const cases = (expected as unknown as { card_layouts: Record<string, Case> }).card_layouts;

function close(actual: unknown, want: unknown, path: string): void {
  if (typeof want === 'number' && typeof actual === 'number') {
    const tol = 1e-9 * Math.max(1, Math.abs(want));
    if (Math.abs(actual - want) > tol) throw new Error(`${path}: expected ${want}, got ${actual}`);
    return;
  }
  if (Array.isArray(want)) {
    if (!Array.isArray(actual) || actual.length !== want.length) {
      throw new Error(`${path}: expected ${JSON.stringify(want)}, got ${JSON.stringify(actual)}`);
    }
    want.forEach((w, i) => close(actual[i], w, `${path}[${i}]`));
    return;
  }
  if (want && typeof want === 'object') {
    if (!actual || typeof actual !== 'object') throw new Error(`${path}: expected object, got ${JSON.stringify(actual)}`);
    const a = actual as Record<string, unknown>;
    const w = want as Record<string, unknown>;
    expect(Object.keys(a).sort(), `${path} keys`).toEqual(Object.keys(w).sort());
    for (const k of Object.keys(w)) close(a[k], w[k], `${path}.${k}`);
    return;
  }
  if (actual !== want) throw new Error(`${path}: expected ${JSON.stringify(want)}, got ${JSON.stringify(actual)}`);
}

describe('card secondary layouts vs the server', () => {
  for (const [name, c] of Object.entries(cases)) {
    it(name, async () => {
      const { engine, handle } = await openFixture();
      const ref = fixtureRef();
      const names = ref.columns.map((col) => col.name);
      const cols = await engine.columns(handle, names);
      const dtypes = new Map(ref.columns.map((col) => [col.name, col.dtype]));
      const get: ColumnGetter = (n) => (cols[n] ? { values: cols[n], dtype: dtypes.get(n) ?? '' } : undefined);
      const mask = name.endsWith(':masked_in_str')
        ? (await engine.mask(handle, [{ kind: 'in', column: 'category_str', values: ['alpha', 'beta'] }])).mask
        : null;
      const card = c.card;
      const got = ['top_n', 'concentration', 'composition', 'donut'].includes(c.layout)
        ? computeBreakdown(
            get,
            mask,
            ref.rows,
            String(card.column_name),
            String(card.breakdown_col),
            String(card.aggregation),
            Number(card.top_n_count ?? 3),
          )
        : numericLayoutPayload(get, mask, ref.rows, card, String(card.column_name), c.layout);
      close(got, c.payload, name);
    });
  }
});
